// Validate required input fields for subject switch
const body = $input.first().json.body || {};

const guildId = body.guild_id;
const userId = body.user_id;
const threadId = body.thread_id; // Optional
const newSubjectSlug = body.new_subject_slug;

const errors = [];
if (!guildId) errors.push('guild_id');
if (!userId) errors.push('user_id');
if (!newSubjectSlug) errors.push('new_subject_slug');

if (errors.length > 0) {
  return {
    json: {
      valid: false,
      error: {
        code: 400,
        message: `Parametres requis manquants: ${errors.join(', ')}`,
        status: 'BAD_REQUEST'
      }
    }
  };
}

// Validate subject slug format (lowercase, alphanumeric, hyphens)
const slugRegex = /^[a-z0-9-]+$/;
if (!slugRegex.test(newSubjectSlug)) {
  return {
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'new_subject_slug doit etre en minuscules, alphanumerique avec tirets uniquement',
        status: 'BAD_REQUEST'
      }
    }
  };
}

return {
  json: {
    valid: true,
    startTime: Date.now(),
    guild_id: guildId,
    user_id: userId,
    thread_id: threadId || null,
    new_subject_slug: newSubjectSlug
  }
};

// Process current subject response and prepare for update
const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const statusCode = input.statusCode || 200;
const body = input.body || input;

// Handle student not found
if (statusCode === 404 || !body || body.error) {
  return {
    json: {
      found: false,
      error: {
        code: 404,
        message: 'Etudiant non trouve dans cette promotion',
        status: 'STUDENT_NOT_FOUND'
      },
      startTime: prevData.startTime
    }
  };
}

// Handle other API errors
if (statusCode >= 400) {
  return {
    json: {
      found: false,
      error: {
        code: statusCode,
        message: body.error?.message || 'Erreur API backend',
        status: 'API_ERROR'
      },
      startTime: prevData.startTime
    }
  };
}

// Extract student data
const student = body.student || body;
const previousSubject = student.current_subject_slug || null;
const promotionId = student.promotion_id;
const studentId = student.id;

return {
  json: {
    found: true,
    student_id: studentId,
    promotion_id: promotionId,
    previous_subject: previousSubject,
    new_subject_slug: prevData.new_subject_slug,
    guild_id: prevData.guild_id,
    user_id: prevData.user_id,
    thread_id: prevData.thread_id,
    startTime: prevData.startTime
  }
};

// Build final response with expert config and _trace
const expertResponse = $input.first().json;
const processData = $('Process Current Subject').first().json;
const validateData = $('Validate Input').first().json;
const updateResponse = $('Update Subject (API)').first().json;

const expertStatusCode = expertResponse.statusCode || 200;
const expertBody = expertResponse.body || expertResponse;

const updateStatusCode = updateResponse.statusCode || 200;

// Check if update failed
if (updateStatusCode >= 400) {
  return {
    json: {
      success: false,
      error: {
        code: updateStatusCode,
        message: 'Echec de la mise a jour du contexte matiere',
        status: 'UPDATE_FAILED'
      },
      _trace: {
        service_response: updateResponse.body || null,
        latency_ms: Date.now() - processData.startTime
      }
    }
  };
}

// Check if subject/expert not found
if (expertStatusCode === 404 || !expertBody || expertBody.error) {
  return {
    json: {
      success: false,
      error: {
        code: 404,
        message: `Matiere '${validateData.new_subject_slug}' non trouvee dans cette promotion`,
        status: 'SUBJECT_NOT_FOUND'
      },
      _trace: {
        service_response: expertBody || null,
        latency_ms: Date.now() - processData.startTime
      }
    }
  };
}

// Handle other API errors for expert config
if (expertStatusCode >= 400) {
  return {
    json: {
      success: false,
      error: {
        code: expertStatusCode,
        message: expertBody.error?.message || 'Erreur lors de la recuperation de la configuration expert',
        status: 'EXPERT_API_ERROR'
      },
      _trace: {
        service_response: expertBody || null,
        latency_ms: Date.now() - processData.startTime
      }
    }
  };
}

// Extract expert configuration
const subject = expertBody.subject || expertBody;
const expert = subject.expert || {};

// Build successful response
return {
  json: {
    success: true,
    data: {
      previous_subject: processData.previous_subject,
      new_subject: validateData.new_subject_slug,
      subject: {
        id: subject.id,
        name: subject.name,
        slug: subject.slug || validateData.new_subject_slug,
        course_channel_id: subject.course_channel_id || null,
        prof_channel_id: subject.prof_channel_id || null
      },
      expert: {
        expert_id: expert.id || expert.expert_id || `expert-${validateData.new_subject_slug}-001`,
        name: expert.name || subject.name || `Expert ${validateData.new_subject_slug}`,
        rag_collection: expert.rag_collection || `education_${validateData.new_subject_slug}`,
        system_prompt: expert.system_prompt || `Tu es un expert en ${subject.name || validateData.new_subject_slug}. Tu aides les etudiants a comprendre les concepts et a resoudre leurs exercices.`
      },
      student: {
        student_id: processData.student_id,
        promotion_id: processData.promotion_id,
        thread_id: processData.thread_id
      }
    },
    _trace: {
      service_response: expertBody,
      context_switched: true,
      previous_subject: processData.previous_subject,
      new_subject: validateData.new_subject_slug,
      latency_ms: Date.now() - processData.startTime
    }
  }
};

